+QMargins PanelView::cornerMargins() const
+{
+    QMargins margins;
+    if (!m_layerWindow || !containment() || !m_screenToFollow || m_lengthMode != PanelView::LengthMode::FillAvailable) {
+        return margins;
+    }
+
+    // KWin reserves the space of horizontal panels first, so a vertical panel covering the
+    // corners moves back over that space, and horizontal panels leave room for it
+    const QList<PanelView *> panels = m_corona->panelsForScreen(m_screenToFollow);
+    for (PanelView *panel : panels) {
+        if (panel == this || panel->lengthMode() != PanelView::LengthMode::FillAvailable) {
+            continue;
+        }
+        if (formFactor() == Plasma::Types::Horizontal) {
+            if (!panel->coversCorners() || panel->formFactor() != Plasma::Types::Vertical) {
+                continue;
+            }
+            if (panel->location() == Plasma::Types::LeftEdge) {
+                margins.setLeft(std::max(margins.left(), panel->totalThickness()));
+            } else if (panel->location() == Plasma::Types::RightEdge) {
+                margins.setRight(std::max(margins.right(), panel->totalThickness()));
+            }
+        } else if (m_coversCorners && m_layerWindow->exclusionZone() > 0) {
+            if (panel->formFactor() != Plasma::Types::Horizontal || !panel->m_layerWindow || panel->m_layerWindow->exclusionZone() <= 0) {
+                continue;
+            }
+            if (panel->location() == Plasma::Types::TopEdge) {
+                margins.setTop(margins.top() - panel->m_layerWindow->exclusionZone());
+            } else if (panel->location() == Plasma::Types::BottomEdge) {
+                margins.setBottom(margins.bottom() - panel->m_layerWindow->exclusionZone());
+            }
+        }
+    }
+    return margins;
+}
+
+void PanelView::updateCorners()
+{
+    if (m_layerWindow && m_initCompleted) {
+        positionAndResizePanel();
+    }
+}
